+					if err != nil {
+						return "", err
+					}
+					parts = append(parts, s)
+				}
+				return strings.Join(parts, " "), nil
+			}
+			if idx.Start != nil && idx.End == nil && idx.Colon == nil {
+				i, ok := intLiteral(idx.Start)
+				if !ok || i < 0 || i >= len(elems) {
+					return "", fmt.Errorf("index must be int literal")
+				}
+				return c.compileExpr(elems[i])
+			}
+		}
+	}

+func listSliceLiteralExpr(e *parser.Expr) ([]*parser.Expr, bool) {
+	if e == nil || e.Binary == nil || len(e.Binary.Right) != 0 {
+		return nil, false
+	}
+	u := e.Binary.Left
+	if len(u.Ops) != 0 || u.Value == nil || len(u.Value.Ops) != 1 {
+		return nil, false
+	}
+	p := u.Value
+	if p.Target == nil || p.Target.List == nil {
+		return nil, false
+	}
+	op := p.Ops[0]
+	if op.Index == nil || op.Index.Step != nil || op.Index.Colon2 != nil {
+		return nil, false
+	}
+	if op.Index.Colon == nil && op.Index.End == nil {
+		return nil, false
+	}
+	elems := p.Target.List.Elems
+	start := 0
+	end := len(elems)
+	var ok bool
+	if op.Index.Start != nil {
+		start, ok = intLiteral(op.Index.Start)
+		if !ok {
+			return nil, false
+		}
+	}
+	if op.Index.End != nil {
+		end, ok = intLiteral(op.Index.End)
+		if !ok {
+			return nil, false
+		}
+	}
+	if start < 0 {
+		start = 0
+	}
+	if end > len(elems) {
+		end = len(elems)
+	}
+	if start > end {
+		start = end
+	}
+	return elems[start:end], true
+}

+	emitArg := func(a Expr) {
+		if inferType(a) == "bool" {
+			switch ex := a.(type) {
+			case *BinaryExpr:
+				if ex.Op == "in" && inferType(ex.Right) == "String" {
+					a.emit(w)
+					return
+				}
+			case *MethodCallExpr:
+				if ex.Name == "contains" {
+					a.emit(w)
+					return
+				}
+			}
+			io.WriteString(w, "if ")
+			a.emit(w)
+			io.WriteString(w, " { 1 } else { 0 }")
+		} else {
+			a.emit(w)
+		}
+	}
